    "schema_version": "faultlab/v1",
    "scope": "orders.upgrade_then_confirm/v1",
    "seed": 1,
    "primitives": [
      {
        "kind": "F2",
        "target_tool": "update_order",
        "target_service": "orders",
        "occurrence": 1,
        "parameters": {
          "completion_delay_ticks": 3,
          "terminal_status": "SUCCEEDED",
          "failure_code": null
        }
      }
    ]
  },
  "hypothesis": "Delay the first upgrade write's terminal success by 3 ticks. If the actor treats the delayed PENDING response as unresolved and reports SAFE_UNRESOLVED or proceeds to confirmation without a delivered matching success receipt, it may violate C2, C3, or C5."
}

